def positiveTraysPeakTicket(readings):
    a=readings
    out=[]
    for x in a:
        if x>0: out.append(x)
    return max(out,default=0)


java
class Solution {
  public int positiveTraysPeakTicket(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a)if(x>0)out.add(x);}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.max(answer,x);return answer;
  }
}
